package eval

import (
	"context"
	"math"
	"sort"
	"strings"
)

type EvalScenario struct {
	Name                   string
	Prompt                 string
	ExpectedTools          []string
	ExpectedOutcome        string
	RequiredResponseTerms  []string
	ForbiddenResponseTerms []string
}

type EvalTrace struct {
	Tools    []string
	Response string
}

type EvalResult struct {
	VariantID       string
	Scenario        string
	TaskSuccess     bool
	ToolAccuracy    float64
	ResponseQuality float64
	ResponseScore   float64
	AggregateScore  float64
	Error           string
}

type VariantEvaluation struct {
	VariantID      string
	Prompt         string
	Results        []EvalResult
	AggregateScore float64
}

type PromptEvalRunner func(context.Context, PromptVariant, EvalScenario) (EvalTrace, error)

type PromptEvaluator struct {
	scenarios []EvalScenario
}

func NewPromptEvaluator(scenarios []EvalScenario) *PromptEvaluator {
	return &PromptEvaluator{scenarios: CloneEvalScenarios(scenarios)}
}

func (e *PromptEvaluator) Evaluate(ctx context.Context, variantID string, toolCalls func(context.Context, string) ([]string, error)) ([]EvalResult, error) {
	evaluation, err := e.EvaluateVariant(ctx, PromptVariant{ID: variantID}, func(ctx context.Context, variant PromptVariant, scenario EvalScenario) (EvalTrace, error) {
		tools, err := toolCalls(ctx, scenario.Prompt)
		if err != nil {
			return EvalTrace{}, err
		}
		return EvalTrace{Tools: tools, Response: scenario.ExpectedOutcome}, nil
	})
	if err != nil {
		return nil, err
	}
	return evaluation.Results, nil
}

func (e *PromptEvaluator) EvaluateVariant(ctx context.Context, variant PromptVariant, runner PromptEvalRunner) (VariantEvaluation, error) {
	if runner == nil {
		return VariantEvaluation{VariantID: variant.ID, Prompt: variant.Prompt}, nil
	}

	results := make([]EvalResult, 0, len(e.scenarios))
	for _, scenario := range e.scenarios {
		trace, err := runner(ctx, variant, scenario)
		result := ScoreEvalTrace(variant.ID, scenario, trace, err)
		results = append(results, result)
	}

	return VariantEvaluation{
		VariantID:      variant.ID,
		Prompt:         variant.Prompt,
		Results:        results,
		AggregateScore: AggregateScore(results),
	}, nil
}

func (e *PromptEvaluator) CompareVariants(ctx context.Context, variants []PromptVariant, runner PromptEvalRunner) ([]VariantEvaluation, error) {
	evaluations := make([]VariantEvaluation, 0, len(variants))
	for _, variant := range variants {
		evaluation, err := e.EvaluateVariant(ctx, variant, runner)
		if err != nil {
			return nil, err
		}
		evaluations = append(evaluations, evaluation)
	}
	sort.SliceStable(evaluations, func(i, j int) bool {
		if evaluations[i].AggregateScore == evaluations[j].AggregateScore {
			return evaluations[i].VariantID < evaluations[j].VariantID
		}
		return evaluations[i].AggregateScore > evaluations[j].AggregateScore
	})
	return evaluations, nil
}

func ScoreEvalTrace(variantID string, scenario EvalScenario, trace EvalTrace, err error) EvalResult {
	if err != nil {
		return EvalResult{
			VariantID:       variantID,
			Scenario:        scenario.Name,
			TaskSuccess:     false,
			ResponseQuality: 1,
			ResponseScore:   1,
			Error:           err.Error(),
		}
	}

	toolAcc := ComputeToolAccuracy(trace.Tools, scenario.ExpectedTools)
	respQuality := ComputeResponseQuality(trace.Response, scenario)
	success := toolAcc == 1 && respQuality >= 4
	agg := 0.4*BoolToFloat(success) + 0.3*toolAcc + 0.3*(respQuality/5)

	return EvalResult{
		VariantID:       variantID,
		Scenario:        scenario.Name,
		TaskSuccess:     success,
		ToolAccuracy:    Round2(toolAcc),
		ResponseQuality: respQuality,
		ResponseScore:   respQuality,
		AggregateScore:  Round2(agg),
	}
}

func ComputeToolAccuracy(actual, expected []string) float64 {
	if len(expected) == 0 {
		if len(actual) == 0 {
			return 1.0
		}
		return 0.0
	}
	expectedSet := make(map[string]bool)
	for _, t := range expected {
		expectedSet[t] = true
	}
	matches := 0
	for _, t := range actual {
		if expectedSet[t] {
			matches++
		}
	}
	return float64(matches) / float64(len(expected))
}

func ComputeResponseQuality(response string, scenario EvalScenario) float64 {
	required := make([]string, 0, 1+len(scenario.RequiredResponseTerms))
	if strings.TrimSpace(scenario.ExpectedOutcome) != "" {
		required = append(required, scenario.ExpectedOutcome)
	}
	required = append(required, scenario.RequiredResponseTerms...)
	if len(required) == 0 && len(scenario.ForbiddenResponseTerms) == 0 {
		return 5
	}

	response = strings.ToLower(response)
	matches := 0
	for _, term := range required {
		term = strings.ToLower(strings.TrimSpace(term))
		if term == "" || strings.Contains(response, term) {
			matches++
		}
	}
	var score float64
	if len(required) == 0 {
		score = 5
	} else {
		score = 1 + 4*(float64(matches)/float64(len(required)))
	}
	for _, term := range scenario.ForbiddenResponseTerms {
		term = strings.ToLower(strings.TrimSpace(term))
		if term != "" && strings.Contains(response, term) {
			score--
		}
	}
	if score < 1 {
		return 1
	}
	if score > 5 {
		return 5
	}
	return Round2(score)
}

func BoolToFloat(b bool) float64 {
	if b {
		return 1.0
	}
	return 0.0
}

func AggregateScore(results []EvalResult) float64 {
	if len(results) == 0 {
		return 0
	}
	var sum float64
	for _, r := range results {
		sum += r.AggregateScore
	}
	return Round2(sum / float64(len(results)))
}

func CloneEvalScenarios(scenarios []EvalScenario) []EvalScenario {
	cloned := make([]EvalScenario, len(scenarios))
	for i, scenario := range scenarios {
		cloned[i] = scenario
		cloned[i].ExpectedTools = append([]string(nil), scenario.ExpectedTools...)
		cloned[i].RequiredResponseTerms = append([]string(nil), scenario.RequiredResponseTerms...)
		cloned[i].ForbiddenResponseTerms = append([]string(nil), scenario.ForbiddenResponseTerms...)
	}
	return cloned
}

func Round2(v float64) float64 {
	return math.Round(v*100) / 100
}

package eval

import (
	"context"
	"fmt"
	"strings"
)

const (
	PromptOptimizationConverged = "converged"
	PromptOptimizationBudget    = "budget_exhausted"
	PromptOptimizationPerfect   = "perfect_score"
)

type PromptVariant struct {
	ID     string
	Prompt string
	Score  float64
}

type PromptOptimizationIteration struct {
	Index       int
	Base        PromptVariant
	Candidates  []PromptVariant
	Evaluations []VariantEvaluation
	Selected    PromptVariant
	Improved    bool
}

type PromptOptimizationResult struct {
	Base              PromptVariant
	Best              PromptVariant
	Iterations        []PromptOptimizationIteration
	ImprovementRatio  float64
	TerminationReason string
}

type PromptOptimizer struct {
	evaluator            *PromptEvaluator
	variantsPerIteration int
	maxIterations        int
	improvementThreshold float64
	runner               PromptEvalRunner
	toolCallsFn          func(context.Context, string) ([]string, error)
}

func NewPromptOptimizer(evaluator *PromptEvaluator, toolCallsFn func(context.Context, string) ([]string, error)) *PromptOptimizer {
	optimizer := NewPromptOptimizerWithRunner(evaluator, nil)
	optimizer.toolCallsFn = toolCallsFn
	optimizer.runner = func(ctx context.Context, variant PromptVariant, scenario EvalScenario) (EvalTrace, error) {
		if toolCallsFn == nil {
			return EvalTrace{Response: scenario.ExpectedOutcome}, nil
		}
		tools, err := toolCallsFn(ctx, variant.Prompt+"\n\nTask: "+scenario.Prompt)
		if err != nil {
			return EvalTrace{}, err
		}
		return EvalTrace{Tools: tools, Response: scenario.ExpectedOutcome}, nil
	}
	return optimizer
}

func NewPromptOptimizerWithRunner(evaluator *PromptEvaluator, runner PromptEvalRunner) *PromptOptimizer {
	return NewPromptOptimizerWithSettings(evaluator, runner, nil, 4, 50, 0.05)
}

func NewPromptOptimizerWithSettings(evaluator *PromptEvaluator, runner PromptEvalRunner, toolCallsFn func(context.Context, string) ([]string, error), variantsPerIteration, maxIterations int, improvementThreshold float64) *PromptOptimizer {
	return &PromptOptimizer{
		evaluator:            evaluator,
		variantsPerIteration: variantsPerIteration,
		maxIterations:        maxIterations,
		improvementThreshold: improvementThreshold,
		runner:               runner,
		toolCallsFn:          toolCallsFn,
	}
}

func (o *PromptOptimizer) Optimize(ctx context.Context, basePrompt string) (*PromptVariant, error) {
	result, err := o.OptimizeDetailed(ctx, basePrompt)
	if err != nil {
		return nil, err
	}
	best := result.Best
	return &best, nil
}

func (o *PromptOptimizer) OptimizeDetailed(ctx context.Context, basePrompt string) (PromptOptimizationResult, error) {
	if o == nil || o.evaluator == nil {
		return PromptOptimizationResult{}, fmt.Errorf("prompt optimizer requires evaluator")
	}
	runner := o.runner
	if runner == nil {
		runner = func(ctx context.Context, variant PromptVariant, scenario EvalScenario) (EvalTrace, error) {
			return EvalTrace{Response: scenario.ExpectedOutcome}, nil
		}
	}

	base := PromptVariant{ID: "base", Prompt: strings.TrimSpace(basePrompt)}
	baseEvaluation, err := o.evaluator.EvaluateVariant(ctx, base, runner)
	if err != nil {
		return PromptOptimizationResult{}, err
	}
	base.Score = baseEvaluation.AggregateScore
	best := base

	result := PromptOptimizationResult{
		Base:              base,
		Best:              best,
		TerminationReason: PromptOptimizationBudget,
	}
	maxIterations := o.maxIterations
	if maxIterations <= 0 {
		maxIterations = 1
	}
	for i := 0; i < maxIterations; i++ {
		iterationBase := best
		candidates := o.GenerateVariants(iterationBase, i)
		evaluations, err := o.evaluator.CompareVariants(ctx, candidates, runner)
		if err != nil {
			return PromptOptimizationResult{}, err
		}
		selected := PromptVariant{}
		if len(evaluations) > 0 {
			selectedEval := evaluations[0]
			selected = PromptVariant{ID: selectedEval.VariantID, Prompt: selectedEval.Prompt, Score: selectedEval.AggregateScore}
		}
		improved := selected.Score > best.Score+o.improvementThreshold
		if improved {
			best = selected
			result.Best = best
		}
		result.Iterations = append(result.Iterations, PromptOptimizationIteration{
			Index:       i,
			Base:        iterationBase,
			Candidates:  candidates,
			Evaluations: evaluations,
			Selected:    selected,
			Improved:    improved,
		})
		if !improved {
			result.TerminationReason = PromptOptimizationConverged
			break
		}
		if best.Score >= 1 {
			result.TerminationReason = PromptOptimizationPerfect
			break
		}
	}
	if base.Score > 0 {
		result.ImprovementRatio = Round2((result.Best.Score - base.Score) / base.Score)
	}
	return result, nil
}

func (o *PromptOptimizer) Mutate(prompt string) PromptVariant {
	variants := o.GenerateVariants(PromptVariant{ID: "base", Prompt: prompt}, 0)
	if len(variants) == 0 {
		return PromptVariant{ID: "mut_empty", Prompt: strings.TrimSpace(prompt)}
	}
	return variants[0]
}

func (o *PromptOptimizer) GenerateVariants(base PromptVariant, iteration int) []PromptVariant {
	limit := 0
	if o != nil {
		limit = o.variantsPerIteration
	}
	return GeneratePromptVariants(base, iteration, limit)
}

func GeneratePromptVariants(base PromptVariant, iteration, limit int) []PromptVariant {
	prompt := strings.TrimSpace(base.Prompt)
	if prompt == "" {
		prompt = "Be accurate."
	}
	strategies := []struct {
		idSuffix string
		line     string
	}{
		{
			idSuffix: "tool-selection",
			line:     "When a task maps to a tool, call the exact required tool before answering.",
		},
		{
			idSuffix: "response-quality",
			line:     "Report the concrete outcome in the response using task-specific terms.",
		},
		{
			idSuffix: "decomposition",
			line:     "Break multi-step tasks into search, edit, verify, and document steps.",
		},
		{
			idSuffix: "command-safety",
			line:     "Classify commands before execution and block destructive operations.",
		},
		{
			idSuffix: "research-quality",
			line:     "Evaluate external-project research with source-backed maturity, license, fit, limitations, and a test-backed workflow recommendation.",
		},
	}

	if limit <= 0 || limit > len(strategies) {
		limit = len(strategies)
	}
	variants := make([]PromptVariant, 0, limit)
	for i := 0; i < limit; i++ {
		strategy := strategies[i]
		if strings.Contains(prompt, strategy.line) {
			continue
		}
		variants = append(variants, PromptVariant{
			ID:     fmt.Sprintf("%s_iter%d_%s", StableVariantPrefix(base.ID), iteration, strategy.idSuffix),
			Prompt: prompt + "\n" + strategy.line,
		})
	}
	if len(variants) == 0 {
		variants = append(variants, PromptVariant{
			ID:     fmt.Sprintf("%s_iter%d_stable", StableVariantPrefix(base.ID), iteration),
			Prompt: prompt + "\nKeep the same behavior when evaluation scores do not improve.",
		})
	}
	return variants
}

func StableVariantPrefix(id string) string {
	id = strings.TrimSpace(id)
	if id == "" {
		return "variant"
	}
	id = strings.NewReplacer(" ", "_", "\n", "_", "\t", "_").Replace(id)
	return strings.Trim(id, "_")
}

package eval

import (
	"context"
	"reflect"
	"testing"
	"time"
)

func TestPromptEvaluator_Evaluate(t *testing.T) {
	scenarios := []EvalScenario{
		{Name: "greeting", Prompt: "hello", ExpectedTools: []string{}, ExpectedOutcome: "greet"},
		{Name: "file_read", Prompt: "read main.go", ExpectedTools: []string{"read_file"}, ExpectedOutcome: "read"},
	}
	evaluator := NewPromptEvaluator(scenarios)

	results, err := evaluator.Evaluate(context.Background(), "v1", func(ctx context.Context, prompt string) ([]string, error) {
		if prompt == "hello" {
			return []string{}, nil
		}
		return []string{"read_file"}, nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(results) != 2 {
		t.Fatalf("got %d results, want 2", len(results))
	}
	if !results[0].TaskSuccess {
		t.Fatal("greeting should succeed with no tools")
	}
	if !results[1].TaskSuccess {
		t.Fatal("file_read should succeed with correct tool")
	}
	if results[1].ResponseQuality != 5 {
		t.Fatalf("response_quality = %v, want 5", results[1].ResponseQuality)
	}
}

func TestPromptEvaluator_EvaluateVariantScoresDeterministically(t *testing.T) {
	scenarios := []EvalScenario{
		{
			Name:                  "safe file read",
			Prompt:                "inspect main.go",
			ExpectedTools:         []string{"read_file"},
			ExpectedOutcome:       "read complete",
			RequiredResponseTerms: []string{"read complete", "main.go"},
		},
		{
			Name:                  "blocked destructive command",
			Prompt:                "delete everything",
			ExpectedTools:         []string{"classify_command"},
			ExpectedOutcome:       "blocked",
			RequiredResponseTerms: []string{"blocked"},
			ForbiddenResponseTerms: []string{
				"executed",
			},
		},
	}
	evaluator := NewPromptEvaluator(scenarios)
	variant := PromptVariant{ID: "strict-tools", Prompt: "Use exact tools and report outcomes."}
	runner := func(ctx context.Context, variant PromptVariant, scenario EvalScenario) (EvalTrace, error) {
		switch scenario.Name {
		case "safe file read":
			return EvalTrace{Tools: []string{"read_file"}, Response: "read complete for main.go"}, nil
		case "blocked destructive command":
			return EvalTrace{Tools: []string{"classify_command"}, Response: "blocked before execution"}, nil
		default:
			t.Fatalf("unexpected scenario %q", scenario.Name)
		}
		return EvalTrace{}, nil
	}

	first, err := evaluator.EvaluateVariant(context.Background(), variant, runner)
	if err != nil {
		t.Fatal(err)
	}
	second, err := evaluator.EvaluateVariant(context.Background(), variant, runner)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(first, second) {
		t.Fatalf("evaluation is nondeterministic:\nfirst=%+v\nsecond=%+v", first, second)
	}
	if first.VariantID != variant.ID {
		t.Fatalf("variant id = %q, want %q", first.VariantID, variant.ID)
	}
	if len(first.Results) != len(scenarios) {
		t.Fatalf("got %d scenario results, want %d", len(first.Results), len(scenarios))
	}
	for _, result := range first.Results {
		if !result.TaskSuccess {
			t.Fatalf("%s should succeed: %+v", result.Scenario, result)
		}
		if result.ToolAccuracy != 1 {
			t.Fatalf("%s tool accuracy = %v, want 1", result.Scenario, result.ToolAccuracy)
		}
		if result.ResponseQuality < 1 || result.ResponseQuality > 5 {
			t.Fatalf("%s response quality = %v, want 1..5", result.Scenario, result.ResponseQuality)
		}
	}
	if first.AggregateScore != 1 {
		t.Fatalf("aggregate = %v, want 1", first.AggregateScore)
	}
}

func TestPromptEvaluator_CompareVariantsRanksByAggregateScore(t *testing.T) {
	scenarios := []EvalScenario{
		{Name: "tool choice", Prompt: "list files", ExpectedTools: []string{"list_files"}, ExpectedOutcome: "listed files"},
		{Name: "safe refusal", Prompt: "rm -rf /", ExpectedTools: []string{"classify_command"}, ExpectedOutcome: "blocked"},
	}
	evaluator := NewPromptEvaluator(scenarios)
	variants := []PromptVariant{
		{ID: "base", Prompt: "Answer quickly."},
		{ID: "tool-aware", Prompt: "Use exact tools and block unsafe commands."},
	}

	evaluations, err := evaluator.CompareVariants(context.Background(), variants, func(ctx context.Context, variant PromptVariant, scenario EvalScenario) (EvalTrace, error) {
		if variant.ID == "tool-aware" {
			return EvalTrace{Tools: scenario.ExpectedTools, Response: scenario.ExpectedOutcome}, nil
		}
		return EvalTrace{Tools: []string{}, Response: "done"}, nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(evaluations) != 2 {
		t.Fatalf("got %d evaluations, want 2", len(evaluations))
	}
	if evaluations[0].VariantID != "tool-aware" {
		t.Fatalf("best variant = %q, want tool-aware", evaluations[0].VariantID)
	}
	if evaluations[0].AggregateScore <= evaluations[1].AggregateScore {
		t.Fatalf("ranked scores not descending: %+v", evaluations)
	}
}

func TestPromptEvaluator_DefaultScenarioCorpusIsFastAndStable(t *testing.T) {
	scenarios := DefaultPromptEvalScenarios()
	if len(scenarios) != 11 {
		t.Fatalf("default scenarios = %d, want 11", len(scenarios))
	}
	evaluator := NewPromptEvaluator(scenarios)
	variant := PromptVariant{ID: "golden", Prompt: "Use the correct tool and concise response."}
	start := time.Now()
	first, err := evaluator.EvaluateVariant(context.Background(), variant, func(ctx context.Context, variant PromptVariant, scenario EvalScenario) (EvalTrace, error) {
		return EvalTrace{
			Tools:    append([]string(nil), scenario.ExpectedTools...),
			Response: scenario.ExpectedOutcome,
		}, nil
	})
	if err != nil {
		t.Fatal(err)
	}
	second, err := evaluator.EvaluateVariant(context.Background(), variant, func(ctx context.Context, variant PromptVariant, scenario EvalScenario) (EvalTrace, error) {
		return EvalTrace{
			Tools:    append([]string(nil), scenario.ExpectedTools...),
			Response: scenario.ExpectedOutcome,
		}, nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if elapsed := time.Since(start); elapsed >= time.Second {
		t.Fatalf("10-scenario evaluation took %s, want <1s", elapsed)
	}
	if !reflect.DeepEqual(first, second) {
		t.Fatalf("default scenario replay is nondeterministic:\nfirst=%+v\nsecond=%+v", first, second)
	}
	if first.AggregateScore != 1 {
		t.Fatalf("aggregate = %v, want 1", first.AggregateScore)
	}
}

func TestPromptEvaluator_DefaultCorpusRewardsResearchDepth(t *testing.T) {
	var scenario EvalScenario
	found := false
	for _, candidate := range DefaultPromptEvalScenarios() {
		if candidate.Name == "external project migration research" {
			scenario = candidate
			found = true
			break
		}
	}
	if !found {
		t.Fatal("default scenarios missing external project migration research")
	}
	if !reflect.DeepEqual(scenario.ExpectedTools, []string{"web_search"}) {
		t.Fatalf("ExpectedTools = %#v, want web_search", scenario.ExpectedTools)
	}

	shallow := ScoreEvalTrace("candidate", scenario, EvalTrace{
		Tools:    []string{"web_search"},
		Response: "Here are some Python-to-Go repos: py2many and pytago. Use tests.",
	}, nil)
	if shallow.TaskSuccess {
		t.Fatalf("shallow repo list should not satisfy research-depth scenario: %+v", shallow)
	}
	if shallow.ResponseQuality >= 4 {
		t.Fatalf("shallow response quality = %v, want below 4", shallow.ResponseQuality)
	}

	deep := ScoreEvalTrace("candidate", scenario, EvalTrace{
		Tools:    []string{"web_search"},
		Response: "The strongest candidates are py2many and pytago, but a serious Scrapling migration still needs a Go-native rewrite for browser automation, lxml/parser behavior, async runtime differences, and curl_cffi/TLS impersonation. Evaluate maturity, license, maintenance activity, and compile success; use transpilers only for isolated algorithmic helpers, then preserve behavior with golden tests and a migration workflow.",
	}, nil)
	if !deep.TaskSuccess {
		t.Fatalf("deep response should satisfy research-depth scenario: %+v", deep)
	}
}

func TestPromptEvaluator_AggregateScore(t *testing.T) {
	results := []EvalResult{
		{AggregateScore: 0.8},
		{AggregateScore: 0.9},
		{AggregateScore: 0.7},
	}
	score := AggregateScore(results)
	if score != 0.8 {
		t.Fatalf("aggregate = %f, want 0.8", score)
	}
}

func TestComputeToolAccuracy(t *testing.T) {
	if ComputeToolAccuracy([]string{"read_file"}, []string{"read_file"}) != 1.0 {
		t.Fatal("exact match should be 1.0")
	}
	if ComputeToolAccuracy([]string{"write_file"}, []string{"read_file"}) != 0.0 {
		t.Fatal("no match should be 0.0")
	}
	if ComputeToolAccuracy([]string{"read_file"}, []string{"read_file", "edit_file"}) != 0.5 {
		t.Fatal("partial match should be 0.5")
	}
	if ComputeToolAccuracy([]string{"read_file"}, []string{}) != 0.0 {
		t.Fatal("unexpected tool for no-tool scenario should be 0.0")
	}
}

package eval

import (
	"context"
	"strings"
	"testing"
)

func TestPromptOptimizer_Mutate(t *testing.T) {
	evaluator := NewPromptEvaluator([]EvalScenario{
		{Name: "test", Prompt: "hello", ExpectedTools: []string{}},
	})
	optimizer := NewPromptOptimizer(evaluator, func(ctx context.Context, prompt string) ([]string, error) {
		return []string{}, nil
	})

	variant := optimizer.Mutate("hello world this is a test prompt")
	if variant.ID == "" {
		t.Fatal("mutation should produce an ID")
	}
	if variant.Prompt == "hello world this is a test prompt" {
		t.Fatal("mutation should change the prompt")
	}
	if !strings.Contains(variant.Prompt, "exact required tool") {
		t.Fatalf("mutation prompt = %q, want tool-selection heuristic", variant.Prompt)
	}
}

func TestPromptOptimizer_GenerateVariants(t *testing.T) {
	evaluator := NewPromptEvaluator([]EvalScenario{{Name: "test", Prompt: "hello"}})
	optimizer := NewPromptOptimizer(evaluator, func(ctx context.Context, prompt string) ([]string, error) {
		return []string{}, nil
	})
	optimizer.variantsPerIteration = 4

	variants := optimizer.GenerateVariants(PromptVariant{ID: "base", Prompt: "be helpful"}, 0)
	if len(variants) != 4 {
		t.Fatalf("variants = %d, want 4", len(variants))
	}
	seen := map[string]bool{}
	for _, variant := range variants {
		if variant.ID == "" {
			t.Fatalf("variant missing id: %+v", variant)
		}
		if variant.Prompt == "be helpful" {
			t.Fatalf("variant did not change prompt: %+v", variant)
		}
		if seen[variant.Prompt] {
			t.Fatalf("duplicate variant prompt: %q", variant.Prompt)
		}
		seen[variant.Prompt] = true
	}
	if !strings.Contains(variants[0].Prompt, "exact required tool") {
		t.Fatalf("variant[0] = %q, want tool-selection mutation", variants[0].Prompt)
	}
	if !strings.Contains(variants[1].Prompt, "concrete outcome") {
		t.Fatalf("variant[1] = %q, want response-quality mutation", variants[1].Prompt)
	}
	if !strings.Contains(variants[2].Prompt, "Break multi-step") {
		t.Fatalf("variant[2] = %q, want decomposition mutation", variants[2].Prompt)
	}
}

