package scoring

import (
	"math"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/model"
)

func Trace(variantID string, scenario model.Scenario, trace model.Trace, err error) model.Result {
	if err != nil {
		return model.Result{
			VariantID:       variantID,
			Scenario:        scenario.Name,
			TaskSuccess:     false,
			ResponseQuality: 1,
			ResponseScore:   1,
			Error:           err.Error(),
		}
	}

	toolAcc := ToolAccuracy(trace.Tools, scenario.ExpectedTools)
	respQuality := ResponseQuality(trace.Response, scenario)
	success := toolAcc == 1 && respQuality >= 4
	agg := 0.4*BoolToFloat(success) + 0.3*toolAcc + 0.3*(respQuality/5)

	return model.Result{
		VariantID:       variantID,
		Scenario:        scenario.Name,
		TaskSuccess:     success,
		ToolAccuracy:    Round2(toolAcc),
		ResponseQuality: respQuality,
		ResponseScore:   respQuality,
		AggregateScore:  Round2(agg),
	}
}

func ToolAccuracy(actual, expected []string) float64 {
	if len(expected) == 0 {
		if len(actual) == 0 {
			return 1.0
		}
		return 0.0
	}
	expectedSet := make(map[string]bool)
	for _, t := range expected {
		expectedSet[t] = true
	}
	matches := 0
	for _, t := range actual {
		if expectedSet[t] {
			matches++
		}
	}
	return float64(matches) / float64(len(expected))
}

func ResponseQuality(response string, scenario model.Scenario) float64 {
	required := make([]string, 0, 1+len(scenario.RequiredResponseTerms))
	if strings.TrimSpace(scenario.ExpectedOutcome) != "" {
		required = append(required, scenario.ExpectedOutcome)
	}
	required = append(required, scenario.RequiredResponseTerms...)
	if len(required) == 0 && len(scenario.ForbiddenResponseTerms) == 0 {
		return 5
	}

	response = strings.ToLower(response)
	matches := 0
	for _, term := range required {
		term = strings.ToLower(strings.TrimSpace(term))
		if term == "" || strings.Contains(response, term) {
			matches++
		}
	}
	var score float64
	if len(required) == 0 {
		score = 5
	} else {
		score = 1 + 4*(float64(matches)/float64(len(required)))
	}
	for _, term := range scenario.ForbiddenResponseTerms {
		term = strings.ToLower(strings.TrimSpace(term))
		if term != "" && strings.Contains(response, term) {
			score--
		}
	}
	if score < 1 {
		return 1
	}
	if score > 5 {
		return 5
	}
	return Round2(score)
}

func BoolToFloat(b bool) float64 {
	if b {
		return 1.0
	}
	return 0.0
}

func Aggregate(results []model.Result) float64 {
	if len(results) == 0 {
		return 0
	}
	var sum float64
	for _, r := range results {
		sum += r.AggregateScore
	}
	return Round2(sum / float64(len(results)))
}

func CloneScenarios(scenarios []model.Scenario) []model.Scenario {
	cloned := make([]model.Scenario, len(scenarios))
	for i, scenario := range scenarios {
		cloned[i] = scenario
		cloned[i].ExpectedTools = append([]string(nil), scenario.ExpectedTools...)
		cloned[i].RequiredResponseTerms = append([]string(nil), scenario.RequiredResponseTerms...)
		cloned[i].ForbiddenResponseTerms = append([]string(nil), scenario.ForbiddenResponseTerms...)
	}
	return cloned
}

func Round2(v float64) float64 {
	return math.Round(v*100) / 100
}

package evaluation

import (
	"context"
	"sort"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/model"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/scoring"
)

type Evaluator struct {
	scenarios []model.Scenario
}

func New(scenarios []model.Scenario) *Evaluator {
	return &Evaluator{scenarios: scoring.CloneScenarios(scenarios)}
}

func (e *Evaluator) Evaluate(ctx context.Context, variantID string, toolCalls func(context.Context, string) ([]string, error)) ([]model.Result, error) {
	evaluation, err := e.EvaluateVariant(ctx, model.Variant{ID: variantID}, func(ctx context.Context, variant model.Variant, scenario model.Scenario) (model.Trace, error) {
		tools, err := toolCalls(ctx, scenario.Prompt)
		if err != nil {
			return model.Trace{}, err
		}
		return model.Trace{Tools: tools, Response: scenario.ExpectedOutcome}, nil
	})
	if err != nil {
		return nil, err
	}
	return evaluation.Results, nil
}

func (e *Evaluator) EvaluateVariant(ctx context.Context, variant model.Variant, runner model.Runner) (model.VariantEvaluation, error) {
	if runner == nil {
		return model.VariantEvaluation{VariantID: variant.ID, Prompt: variant.Prompt}, nil
	}

	results := make([]model.Result, 0, len(e.scenarios))
	for _, scenario := range e.scenarios {
		trace, err := runner(ctx, variant, scenario)
		result := scoring.Trace(variant.ID, scenario, trace, err)
		results = append(results, result)
	}

	return model.VariantEvaluation{
		VariantID:      variant.ID,
		Prompt:         variant.Prompt,
		Results:        results,
		AggregateScore: scoring.Aggregate(results),
	}, nil
}

func (e *Evaluator) CompareVariants(ctx context.Context, variants []model.Variant, runner model.Runner) ([]model.VariantEvaluation, error) {
	evaluations := make([]model.VariantEvaluation, 0, len(variants))
	for _, variant := range variants {
		evaluation, err := e.EvaluateVariant(ctx, variant, runner)
		if err != nil {
			return nil, err
		}
		evaluations = append(evaluations, evaluation)
	}
	sort.SliceStable(evaluations, func(i, j int) bool {
		if evaluations[i].AggregateScore == evaluations[j].AggregateScore {
			return evaluations[i].VariantID < evaluations[j].VariantID
		}
		return evaluations[i].AggregateScore > evaluations[j].AggregateScore
	})
	return evaluations, nil
}

package mutation

import (
	"fmt"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/model"
)

func GenerateVariants(base model.Variant, iteration, limit int) []model.Variant {
	prompt := strings.TrimSpace(base.Prompt)
	if prompt == "" {
		prompt = "Be accurate."
	}
	strategies := []struct {
		idSuffix string
		line     string
	}{
		{
			idSuffix: "tool-selection",
			line:     "When a task maps to a tool, call the exact required tool before answering.",
		},
		{
			idSuffix: "response-quality",
			line:     "Report the concrete outcome in the response using task-specific terms.",
		},
		{
			idSuffix: "decomposition",
			line:     "Break multi-step tasks into search, edit, verify, and document steps.",
		},
		{
			idSuffix: "command-safety",
			line:     "Classify commands before execution and block destructive operations.",
		},
		{
			idSuffix: "research-quality",
			line:     "Evaluate external-project research with source-backed maturity, license, fit, limitations, and a test-backed workflow recommendation.",
		},
	}

	if limit <= 0 || limit > len(strategies) {
		limit = len(strategies)
	}
	variants := make([]model.Variant, 0, limit)
	for i := 0; i < limit; i++ {
		strategy := strategies[i]
		if strings.Contains(prompt, strategy.line) {
			continue
		}
		variants = append(variants, model.Variant{
			ID:     fmt.Sprintf("%s_iter%d_%s", StablePrefix(base.ID), iteration, strategy.idSuffix),
			Prompt: prompt + "\n" + strategy.line,
		})
	}
	if len(variants) == 0 {
		variants = append(variants, model.Variant{
			ID:     fmt.Sprintf("%s_iter%d_stable", StablePrefix(base.ID), iteration),
			Prompt: prompt + "\nKeep the same behavior when evaluation scores do not improve.",
		})
	}
	return variants
}

func StablePrefix(id string) string {
	id = strings.TrimSpace(id)
	if id == "" {
		return "variant"
	}
	id = strings.NewReplacer(" ", "_", "\n", "_", "\t", "_").Replace(id)
	return strings.Trim(id, "_")
}

package optimization

import (
	"context"
	"fmt"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/evaluation"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/model"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/mutation"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/prompts/eval/scoring"
)

const (
	Converged    = "converged"
	Budget       = "budget_exhausted"
	PerfectScore = "perfect_score"
)

type Iteration struct {
	Index       int
	Base        model.Variant
	Candidates  []model.Variant
	Evaluations []model.VariantEvaluation
	Selected    model.Variant
	Improved    bool
}

type Result struct {
	Base              model.Variant
	Best              model.Variant
	Iterations        []Iteration
	ImprovementRatio  float64
	TerminationReason string
}

type Optimizer struct {
	evaluator            *evaluation.Evaluator
	variantsPerIteration int
	maxIterations        int
	improvementThreshold float64
	runner               model.Runner
	toolCallsFn          func(context.Context, string) ([]string, error)
}

func New(evaluator *evaluation.Evaluator, toolCallsFn func(context.Context, string) ([]string, error)) *Optimizer {
	optimizer := NewWithRunner(evaluator, nil)
	optimizer.toolCallsFn = toolCallsFn
	optimizer.runner = func(ctx context.Context, variant model.Variant, scenario model.Scenario) (model.Trace, error) {
		if toolCallsFn == nil {
			return model.Trace{Response: scenario.ExpectedOutcome}, nil
		}
		tools, err := toolCallsFn(ctx, variant.Prompt+"\n\nTask: "+scenario.Prompt)
		if err != nil {
			return model.Trace{}, err
		}
		return model.Trace{Tools: tools, Response: scenario.ExpectedOutcome}, nil
	}
	return optimizer
}

func NewWithRunner(evaluator *evaluation.Evaluator, runner model.Runner) *Optimizer {
	return NewWithSettings(evaluator, runner, nil, 4, 50, 0.05)
}

func NewWithSettings(evaluator *evaluation.Evaluator, runner model.Runner, toolCallsFn func(context.Context, string) ([]string, error), variantsPerIteration, maxIterations int, improvementThreshold float64) *Optimizer {
	return &Optimizer{
		evaluator:            evaluator,
		variantsPerIteration: variantsPerIteration,
		maxIterations:        maxIterations,
		improvementThreshold: improvementThreshold,
		runner:               runner,
		toolCallsFn:          toolCallsFn,
	}
}

func (o *Optimizer) Optimize(ctx context.Context, basePrompt string) (*model.Variant, error) {
	result, err := o.OptimizeDetailed(ctx, basePrompt)
	if err != nil {
		return nil, err
	}
	best := result.Best
	return &best, nil
}

func (o *Optimizer) OptimizeDetailed(ctx context.Context, basePrompt string) (Result, error) {
	if o == nil || o.evaluator == nil {
		return Result{}, fmt.Errorf("prompt optimizer requires evaluator")
	}
	runner := o.runner
	if runner == nil {
		runner = func(ctx context.Context, variant model.Variant, scenario model.Scenario) (model.Trace, error) {
			return model.Trace{Response: scenario.ExpectedOutcome}, nil
		}
	}

	base := model.Variant{ID: "base", Prompt: strings.TrimSpace(basePrompt)}
	baseEvaluation, err := o.evaluator.EvaluateVariant(ctx, base, runner)
	if err != nil {
		return Result{}, err
	}
	base.Score = baseEvaluation.AggregateScore
	best := base

	result := Result{
		Base:              base,
		Best:              best,
		TerminationReason: Budget,
	}
	maxIterations := o.maxIterations
	if maxIterations <= 0 {
		maxIterations = 1
	}
	for i := 0; i < maxIterations; i++ {
		iterationBase := best
		candidates := o.GenerateVariants(iterationBase, i)
		evaluations, err := o.evaluator.CompareVariants(ctx, candidates, runner)
		if err != nil {
			return Result{}, err
		}
		selected := model.Variant{}
		if len(evaluations) > 0 {
			selectedEval := evaluations[0]
			selected = model.Variant{ID: selectedEval.VariantID, Prompt: selectedEval.Prompt, Score: selectedEval.AggregateScore}
		}
		improved := selected.Score > best.Score+o.improvementThreshold
		if improved {
			best = selected
			result.Best = best
		}
		result.Iterations = append(result.Iterations, Iteration{
			Index:       i,
			Base:        iterationBase,
			Candidates:  candidates,
			Evaluations: evaluations,
			Selected:    selected,
			Improved:    improved,
		})
		if !improved {
			result.TerminationReason = Converged
			break
		}
		if best.Score >= 1 {
			result.TerminationReason = PerfectScore
			break
		}
	}
	if base.Score > 0 {
		result.ImprovementRatio = scoring.Round2((result.Best.Score - base.Score) / base.Score)
	}
	return result, nil
}

func (o *Optimizer) Mutate(prompt string) model.Variant {
	variants := o.GenerateVariants(model.Variant{ID: "base", Prompt: prompt}, 0)
	if len(variants) == 0 {
		return model.Variant{ID: "mut_empty", Prompt: strings.TrimSpace(prompt)}
	}
	return variants[0]
}

func (o *Optimizer) GenerateVariants(base model.Variant, iteration int) []model.Variant {
	limit := 0
	if o != nil {
		limit = o.variantsPerIteration
	}
	return mutation.GenerateVariants(base, iteration, limit)
}

